package cli

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/spf13/cobra"
)

const (
	schemeHTTP  = "http"
	schemeHTTPS = "https"
)

const fallbackDeviceAuthPollInterval = time.Second
const defaultSlowDownBackoff = 5 * time.Second
const maxPollInterval = 30 * time.Second
const maxExpiresIn = 15 * time.Minute
const maxTransientErrors = 5

// browserOpenFunc is the signature for opening a URL in the user's browser.
type browserOpenFunc func(ctx context.Context, url string) error

// chooseApprovalURL prefers verification_uri_complete (RFC 8628 §3.3.1) so the
// browser lands on a URL with the user_code already in the query string —
// most verification pages prefill the input from that param, sparing the
// user from typing. Falls back to the bare verification_uri when the AS
// didn't supply a complete form.
func chooseApprovalURL(start *auth.DeviceAuthStart) string {
	if start.VerificationURIComplete != "" {
		return start.VerificationURIComplete
	}
	return start.VerificationURI
}

// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
type deviceAuthClient interface {
	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
	BaseURL() string
}

func newLoginCmd() *cobra.Command {
	var (
		insecureHTTPAuth bool
		server           string
	)
	cmd := &cobra.Command{
		Use:   "login",
		Short: "Log in to Entire",
		RunE: func(cmd *cobra.Command, _ []string) error {
			loginServer, err := parseLoginServer(server)
			if err != nil {
				return fmt.Errorf("invalid --server: %w", err)
			}
			if err := requireSecureLoginServer(loginServer, insecureHTTPAuth); err != nil {
				return err
			}
			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), auth.NewClient(loginServer, nil, insecureHTTPAuth), openBrowser)
		},
	}
	cmd.Flags().StringVar(&server, "server", api.DefaultAuthBaseURL,
		"login server to authenticate against (rarely needed; the default serves all standard accounts)")
	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
	return cmd
}

// parseLoginServer validates and canonicalises the --server value: an
// http(s) origin with nothing but scheme and host. Userinfo, path, query,
// and fragment are rejected rather than silently dropped — the value
// becomes the OAuth issuer, the token-exchange target, and the keyring
// key, so surprising rewrites would surface as confusing auth failures
// much later. A lone trailing slash is tolerated (normalised away).
func parseLoginServer(raw string) (string, error) {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "", errors.New("empty server URL")
	}
	u, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("parse server URL: %w", err)
	}
	switch {
	case u.Scheme != schemeHTTPS && u.Scheme != schemeHTTP:
		return "", fmt.Errorf("scheme must be http or https, got %q", raw)
	case u.Host == "":
		return "", fmt.Errorf("missing host in %q", raw)
	case u.User != nil:
		return "", fmt.Errorf("userinfo not allowed in %q", raw)
	case u.Path != "" && u.Path != "/":
		return "", fmt.Errorf("path not allowed in %q (use the bare origin)", raw)
	case u.RawQuery != "" || u.Fragment != "":
		return "", fmt.Errorf("query/fragment not allowed in %q", raw)
	}
	return api.NormalizeOriginURL(raw), nil
}

// requireSecureLoginServer enforces TLS for the chosen login server.
// Unlike requireSecureBaseURL it checks only the server being dialled —
// login never touches the data API. --insecure-http-auth opts in to
// http:// (and enables it process-wide for the token save path).
func requireSecureLoginServer(server string, insecureHTTPAuth bool) error {
	if insecureHTTPAuth {
		auth.EnableInsecureHTTP()
		return nil
	}
	if err := api.RequireSecureURL(server); err != nil {
		return fmt.Errorf("login server check: %w", err)
	}
	return nil
}

func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
	start, err := client.StartDeviceAuth(ctx)
	if err != nil {
		return fmt.Errorf("start login: %w", err)
	}

	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)

	approvalURL := chooseApprovalURL(start)

	if interactive.CanPromptInteractively() {
		// chooseApprovalURL prefers the code-embedded verification_uri_complete,
		// so opening the URL is usually all the user needs to do. The device
		// code is printed above regardless, so it's still available to confirm
		// against the page (RFC 8628 §3.3.1) or to enter on the bare-URI fallback.
		fmt.Fprintf(outW, "Login URL:   %s\n\n", approvalURL)
		fmt.Fprintf(outW, "Press Enter to open in browser...")

		// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
		if err := waitForEnter(ctx); err != nil {
			return fmt.Errorf("wait for input: %w", err)
		}

		fmt.Fprintln(outW)
		if err := openURL(ctx, approvalURL); err != nil {
			fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
			fmt.Fprintf(outW, "Open this URL in your browser to approve this login: %s\n", approvalURL)
		}
	} else {
		fmt.Fprintf(outW, "Login URL:   %s\n\n", approvalURL)
	}

	fmt.Fprint(outW, "Waiting for approval... ")

	token, refreshToken, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, time.Duration(start.Interval)*time.Second, defaultSlowDownBackoff)
	if err != nil {
		return fmt.Errorf("complete login: %w", err)
	}

	if err := validateReceivedToken(token, client.BaseURL(), time.Now()); err != nil {
		return fmt.Errorf("reject login token: %w", err)
	}

	store := auth.NewStore()

	// Login deliberately uses the legacy SaveToken (string, string)
	// surface — we only have an access-token string at this point;
	// the deviceflow client doesn't return a TokenSet here.
	if err := store.SaveToken(client.BaseURL(), token); err != nil {
		return fmt.Errorf("save auth token: %w", err)
	}

	// Dual-write the shared contexts.json credential model so the git
	// remote helper (and entiredb's CLIs) can authenticate against any
	// entitled cluster from this login. Best-effort: the legacy entry
	// above remains the control-plane source of truth, so a failure here
	// must not fail the login — warn and continue.
	if _, err := auth.RecordLoginContext(token, refreshToken, true); err != nil {
		fmt.Fprintf(errW, "Warning: logged in, but could not record a shareable context (clone via entire:// may need a re-login): %v\n", err)
	}

	fmt.Fprintln(outW, "✓ Login complete.")
	return nil
}

// validateReceivedToken runs minimum-trust checks on the access token
// the AS handed us before we persist it. The server is the authority
// on signature/exp; this is defense in depth aimed at catching gross
// misbehaviour by a compromised or misconfigured AS (e.g. handing back
// a token from a different issuer than the one we asked, or one whose
// claims are already-expired).
//
// Opaque (non-JWT) tokens are permitted — the AS may not issue JWTs at
// all. Only when we can parse the token as a JWT do we cross-check the
// claims. Unsigned (alg:none) JWTs are always rejected via
// tokens.ErrUnsignedJWT; every other parse failure (3-segment-but-not-
// base64, payload-not-JSON, header-not-JSON, etc.) is treated as opaque
// and accepted, so a server issuing dot-bearing non-JWT bearer tokens
// can still log in.
func validateReceivedToken(rawToken, issuerURL string, now time.Time) error {
	claims, err := tokens.ParseClaims(rawToken)
	if errors.Is(err, tokens.ErrUnsignedJWT) {
		return err //nolint:wrapcheck // sentinel surfaces verbatim for caller's errors.Is
	}
	if err != nil {
		return nil //nolint:nilerr // any parse failure other than alg:none means the token isn't a JWT — opaque tokens are valid
	}

	// iss check: the token must claim to come from the issuer we sent
	// the device-code request to. A mismatch means either the AS is
	// misconfigured or someone's playing games.
	if issErr := issMatches(claims.Issuer, issuerURL); issErr != nil {
		return issErr
	}

	// exp sanity: a token that's already expired before we even store
	// it is a smell. Don't reject if exp is unset (some servers omit).
	if !claims.ExpiresAt.IsZero() && !now.Before(claims.ExpiresAt) {
		return fmt.Errorf("token already expired (exp=%s, now=%s)",
			claims.ExpiresAt.Format(time.RFC3339), now.Format(time.RFC3339))
	}

	return nil
}

// issMatches reports whether claimed equals expected after stripping path/
// query/fragment via api.OriginOnly, so "https://issuer/" and "https://issuer"
// match. Returns nil on match or when the iss claim is empty (some servers
// omit it — the server still does the real check on every request).
func issMatches(claimed, expected string) error {
	if claimed == "" {
		return nil
	}
	normClaimed := api.OriginOnly(claimed)
	normExpected := api.OriginOnly(expected)
	if normClaimed != normExpected {
		return fmt.Errorf("iss mismatch: token claims %q, expected %q", normClaimed, normExpected)
	}
	return nil
}

func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn int, interval, slowDownBackoff time.Duration) (accessToken, refreshToken string, err error) {
	expiry := time.Duration(expiresIn) * time.Second
	if expiry <= 0 || expiry > maxExpiresIn {
		expiry = maxExpiresIn
	}
	deadline := time.Now().Add(expiry)
	pollInterval := interval
	if pollInterval <= 0 {
		pollInterval = fallbackDeviceAuthPollInterval
	}

	consecutiveErrors := 0

	for {
		if time.Now().After(deadline) {
			return "", "", errors.New("device authorization expired")
		}

		result, err := poller.PollDeviceAuth(ctx, deviceCode)
		if err != nil {
			consecutiveErrors++
			if consecutiveErrors >= maxTransientErrors {
				return "", "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
			}
			// Transient error — wait and retry.
			select {
			case <-ctx.Done():
				return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
			case <-time.After(pollInterval):
			}
			continue
		}
		consecutiveErrors = 0

		switch result.Error {
		case "":
			if result.AccessToken == "" {
				return "", "", errors.New("device authorization completed without a token")
			}
			return result.AccessToken, result.RefreshToken, nil
		case "authorization_pending":
			// no-op, will sleep and retry below
		case "slow_down":
			pollInterval += slowDownBackoff
			if pollInterval > maxPollInterval {
				pollInterval = maxPollInterval
			}
		case "access_denied":
			return "", "", errors.New("device authorization denied")
		case "expired_token":
			return "", "", errors.New("device authorization expired")
		default:
			if result.ErrorDescription != "" {
				return "", "", fmt.Errorf("device authorization failed: %s: %s", result.Error, result.ErrorDescription)
			}
			return "", "", fmt.Errorf("device authorization failed: %s", result.Error)
		}

		select {
		case <-ctx.Done():
			return "", "", fmt.Errorf("wait for approval: %w", ctx.Err())
		case <-time.After(pollInterval):
		}
	}
}

// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
// Returns ctx.Err() if the context is cancelled before the user presses Enter.
func waitForEnter(ctx context.Context) error {
	tty, err := os.Open("/dev/tty")
	if err != nil {
		return nil //nolint:nilerr // tty unavailable (e.g. Windows) — skip prompt silently
	}

	done := make(chan error, 1)
	go func() {
		reader := bufio.NewReader(tty)
		_, err := reader.ReadString('\n')
		done <- err
	}()

	select {
	case <-ctx.Done():
		// Close tty to unblock the reading goroutine.
		_ = tty.Close()
		return fmt.Errorf("interrupted: %w", ctx.Err())
	case <-done:
		_ = tty.Close()
		return nil
	}
}

func openBrowser(ctx context.Context, browserURL string) error {
	u, err := url.Parse(browserURL)
	if err != nil || (u.Scheme != schemeHTTPS && u.Scheme != schemeHTTP) {
		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
	}

	var command string
	var args []string

	switch runtime.GOOS {
	case "darwin":
		command = "open"
		args = []string{browserURL}
	case "linux":
		command = "xdg-open"
		args = []string{browserURL}
	case "windows":
		command = "cmd"
		args = []string{"/c", "start", "", browserURL}
	default:
		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
	}

	cmd := exec.CommandContext(ctx, command, args...)
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start browser command %q: %w", command, err)
	}

	if err := cmd.Process.Release(); err != nil {
		return fmt.Errorf("release browser process: %w", err)
	}

	return nil
}

package cli

import (
	"context"
	"fmt"
	"io"
	"net/http"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/spf13/cobra"
)

// tokenStore abstracts keyring access so commands that read or delete the
// stored bearer token can be unit-tested without hitting the real OS keyring.
// Used by logout and the auth subcommands.
type tokenStore interface {
	GetToken(baseURL string) (string, error)
	DeleteToken(baseURL string) error
}

// boundRevokeFunc revokes login session(s) server-side — either just the
// current session or every session on the core, depending on which the caller
// selected (--everywhere). The caller resolves the active context's core URL +
// bearer up-front and binds them into the closure, so the revocation hits the
// same core that `auth status` lists.
type boundRevokeFunc func(ctx context.Context) error

// clearContextFunc removes the active contexts.json context (and its
// keyring token) so logout actually logs out under the contexts model.
// Injected so logout stays unit-testable without touching the real
// config dir.
type clearContextFunc func() error

func newLogoutCmd() *cobra.Command {
	var insecureHTTPAuth bool
	var everywhere bool
	var allContexts bool
	cmd := &cobra.Command{
		Use:   "logout",
		Short: "Log out of Entire",
		Long: "Log out of Entire.\n\n" +
			"By default this ends the active session only (server-side) and removes the\n" +
			"active login from this machine. Other saved logins (contexts) remain and can\n" +
			"still authenticate `git clone entire://…` against clusters fronted by their\n" +
			"login server.\n\n" +
			"Pass --everywhere to revoke every session on the active login server\n" +
			"(all your devices), not just the current one.\n\n" +
			"Pass --all-contexts to log out of every saved login (context) at once: each\n" +
			"context's session is revoked server-side and the login is removed from this\n" +
			"machine. Combine with --everywhere to revoke every session on every context's\n" +
			"login server.\n\n" +
			"Without --all-contexts, logging out promotes the next saved login (if any) to\n" +
			"active, so running `entire logout` repeatedly drains every saved login in turn.",
		RunE: func(cmd *cobra.Command, _ []string) error {
			if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
				return err
			}
			outW, errW := cmd.OutOrStdout(), cmd.ErrOrStderr()

			// Pick the per-target revocation: just the current session, or
			// every session on that context's core when --everywhere is set.
			revokeForTarget := revokeCurrentAuthSession
			if everywhere {
				revokeForTarget = revokeAllAuthSessions
			}

			if allContexts {
				return runLogoutAll(cmd.Context(), outW, errW, auth.Contexts,
					auth.LoginTokenForContext, revokeForTarget, auth.RemoveContext,
					auth.NewContextStore(), api.AuthBaseURL(), insecureHTTPAuth)
			}

			// Revoke against the active context's core (matching what
			// `auth status` lists), not a static AuthBaseURL. The refreshing
			// resolver means an expired-but-refreshable session still yields a
			// bearer that can authenticate the revoke call.
			target, err := resolveStatusTarget(cmd.Context(), auth.NewContextStore(), auth.Contexts, auth.RefreshedLoginToken, api.AuthBaseURL())
			if err != nil {
				return err
			}
			if !insecureHTTPAuth {
				if err := api.RequireSecureURL(target.coreURL); err != nil {
					return fmt.Errorf("context login server URL check: %w", err)
				}
			}
			revoke := func(ctx context.Context) error {
				return revokeForTarget(ctx, target.coreURL, target.token)
			}
			if err := runLogout(cmd.Context(), outW, errW,
				auth.NewContextStore(), revoke,
				auth.RemoveCurrentContext, api.AuthBaseURL()); err != nil {
				return err
			}
			promoteNextLogin(outW, errW)
			return nil
		},
	}
	cmd.Flags().BoolVar(&everywhere, "everywhere", false, "Revoke every session server-side, not just the current one")
	cmd.Flags().BoolVar(&allContexts, "all-contexts", false, "Log out of every saved login (context), not just the active one")
	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
	return cmd
}

// promoteNextLogin makes the first remaining saved context active after a
// logout cleared the previous one. This is what lets `entire logout` drain
// every login when run repeatedly: each call ends the active login and
// promotes the next, until none remain. Best-effort and informational —
// logout already succeeded by the time we get here.
func promoteNextLogin(outW, errW io.Writer) {
	all, current, err := auth.Contexts()
	if err != nil || current != "" || len(all) == 0 {
		return
	}
	next := all[0].Name
	if err := auth.SetCurrentContext(next); err != nil {
		fmt.Fprintf(errW, "Note: %d saved login(s) remain; run `entire auth use <context>` to switch.\n", len(all))
		return
	}
	fmt.Fprintf(outW, "Now using %q (%d saved login(s) remain; run `entire logout` again to remove each).\n", next, len(all))
}

// revokeCurrentAuthSession revokes the active session on coreURL (the family the
// bearer belongs to) — the default `entire logout`.
func revokeCurrentAuthSession(ctx context.Context, coreURL, token string) error {
	return newAuthSessionsClient(coreURL, token).RevokeCurrentAuthSession(ctx) //nolint:wrapcheck // RevokeCurrentAuthSession already wraps with action context
}

// revokeAllAuthSessions revokes every active login session on coreURL (the
// `entire logout --everywhere` path): list the families, then delete each by id.
// Best-effort across sessions — it attempts them all and returns the first
// failure, so one stuck session doesn't strand the rest.
func revokeAllAuthSessions(ctx context.Context, coreURL, token string) error {
	client := newAuthSessionsClient(coreURL, token)
	// ListAuthSessions and RevokeAuthSession already wrap with their own action
	// context (incl. the session id), so return their errors verbatim.
	sessions, err := client.ListAuthSessions(ctx)
	if err != nil {
		return err //nolint:wrapcheck // ListAuthSessions already wraps with "list sessions"
	}
	var firstErr error
	for _, s := range sessions {
		if err := client.RevokeAuthSession(ctx, s.ID); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// runLogout ends the user's login. revoke is the caller-selected server-side
// revocation — just the active session, or every session on the active core
// when --everywhere is set. Either way the local keyring entry and active
// context are removed, so the CLI reports logged-out even if the server call
// fails.
func runLogout(ctx context.Context, outW, errW io.Writer, store tokenStore, revoke boundRevokeFunc, clearContext clearContextFunc, baseURL string) error {
	token, err := store.GetToken(baseURL)
	if err != nil {
		// Fall through to the local delete: we still want the keyring entry
		// gone, even if we couldn't read it well enough to revoke server-side.
		fmt.Fprintf(errW, "Warning: failed to read token before revocation: %v\n", err)
	}
	if token != "" {
		if err := revoke(ctx); err != nil && !api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
			// Best-effort: a transient network error shouldn't block local
			// logout. A 401 means the token is already invalid server-side,
			// so the desired state is achieved — no warning needed.
			fmt.Fprintf(errW, "Warning: server-side session revocation failed: %v\n", err)
		}
	}

	if err := store.DeleteToken(baseURL); err != nil {
		return fmt.Errorf("remove auth token: %w", err)
	}

	// Remove the active context so the context-preferring readers no longer
	// report a login. Best-effort: the legacy entry is already gone above.
	if err := clearContext(); err != nil {
		fmt.Fprintf(errW, "Warning: failed to clear current context: %v\n", err)
	}

	fmt.Fprintln(outW, "Logged out.")
	return nil
}

// revokeTargetFunc revokes sessions on a specific core. The two production
// implementations are revokeCurrentAuthSession (just the bearer's own session)
// and revokeAllAuthSessions (every session on that core); `logout --all-contexts` picks
// one based on --everywhere and applies it to each saved context's core.
type revokeTargetFunc func(ctx context.Context, coreURL, token string) error

// runLogoutAll drains every saved login. For each context it revokes the
// session(s) on that context's own core (using its own bearer) and removes
// the login locally, then clears the legacy keyring entry. Per-context
// failures warn but never abort the sweep — one stuck login can't strand the
// rest, and local removal always proceeds so the CLI ends fully logged out.
//
// Dependencies are injected so the sweep is unit-testable without the real
// keyring or config dir: listContexts (auth.Contexts), tokenForContext
// (auth.LoginTokenForContext), revoke (revokeCurrentAuthSession/revokeAllAuthSessions),
// and removeContext (auth.RemoveContext).
func runLogoutAll(ctx context.Context, outW, errW io.Writer,
	listContexts contextsProvider,
	tokenForContext func(*contexts.Context) (string, error),
	revoke revokeTargetFunc,
	removeContext func(name string) error,
	store tokenStore, baseURL string, insecureHTTPAuth bool,
) error {
	all, _, err := listContexts()
	if err != nil {
		return fmt.Errorf("list saved logins: %w", err)
	}

	removed := 0
	for _, c := range all {
		token, terr := tokenForContext(c)
		if terr != nil {
			// Can't read this context's bearer — skip the server revoke but
			// still drop it locally so it stops being reported as a login.
			fmt.Fprintf(errW, "Warning: couldn't read token for %q; removing locally only: %v\n", c.Name, terr)
			token = ""
		}
		if token != "" && c.CoreURL != "" && !insecureHTTPAuth {
			if serr := api.RequireSecureURL(c.CoreURL); serr != nil {
				// Never send a bearer over a non-TLS core; warn and skip the
				// server revoke, but still remove the login locally.
				fmt.Fprintf(errW, "Warning: skipping server-side revocation for %q: %v\n", c.Name, serr)
				token = ""
			}
		}
		if token != "" && c.CoreURL != "" {
			if rerr := revoke(ctx, c.CoreURL, token); rerr != nil && !api.IsHTTPErrorStatus(rerr, http.StatusUnauthorized) {
				fmt.Fprintf(errW, "Warning: server-side session revocation failed for %q: %v\n", c.Name, rerr)
			}
		}
		if rerr := removeContext(c.Name); rerr != nil {
			fmt.Fprintf(errW, "Warning: failed to remove saved login %q: %v\n", c.Name, rerr)
			continue
		}
		removed++
	}

	// Clear the legacy keyring entry too so a pre-contexts login doesn't
	// linger after a full logout. Best-effort: the contexts above are the
	// source of truth for the logged-out state.
	if derr := store.DeleteToken(baseURL); derr != nil {
		fmt.Fprintf(errW, "Warning: failed to remove legacy auth token: %v\n", derr)
	}

	if removed == 0 {
		fmt.Fprintln(outW, "No saved logins to remove.")
	} else {
		fmt.Fprintf(outW, "Logged out of %d saved login(s).\n", removed)
	}
	return nil
}

package api

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"strings"
)

// ErrInsecureHTTP is returned when the base URL uses HTTP without an explicit opt-in.
var ErrInsecureHTTP = errors.New("refusing to use insecure http:// base URL for authentication (use --insecure-http-auth to override)")

const (
	// DefaultBaseURL is the production Entire API origin.
	DefaultBaseURL = "https://entire.io"

	// DefaultAuthBaseURL is the production Entire auth origin (device flow,
	// auth-token management, keyring key). The CLI is split-host by default:
	// auth on us.auth.entire.io, data on entire.io.
	DefaultAuthBaseURL = "https://us.auth.entire.io"

	// BaseURLEnvVar overrides the Entire API origin for local development.
	BaseURLEnvVar = "ENTIRE_API_BASE_URL"

	// AuthBaseURLEnvVar overrides only the auth/login origin (device flow,
	// auth-tokens management, keyring key). Falls back to DefaultAuthBaseURL
	// when unset; local-dev and single-host deployments must set this
	// alongside ENTIRE_API_BASE_URL.
	AuthBaseURLEnvVar = "ENTIRE_AUTH_BASE_URL"

	schemeHTTP  = "http"
	schemeHTTPS = "https"
)

// RejectRemovedAuthEnv returns an error when ENTIRE_AUTH_BASE_URL is set
// at all (even empty). The variable is retired in favour of
// `entire login --server`; failing loudly beats silently ignoring an
// override the operator believes is in effect. The remaining internal
// AuthBaseURL() reads only ever see the default once this gate has run.
func RejectRemovedAuthEnv() error {
	if _, ok := os.LookupEnv(AuthBaseURLEnvVar); ok {
		return fmt.Errorf("%s is no longer supported; unset it, and use `entire login --server <url>` to log in to a non-default login server", AuthBaseURLEnvVar)
	}
	return nil
}

// BaseURL returns the effective Entire API base URL.
// ENTIRE_API_BASE_URL takes precedence over the production default.
func BaseURL() string {
	if raw := strings.TrimSpace(os.Getenv(BaseURLEnvVar)); raw != "" {
		return normalizeBaseURL(raw)
	}

	return DefaultBaseURL
}

// AuthBaseURL returns the origin used for the device-flow login, auth-token
// management endpoints, and the keyring key under which the bearer token is
// stored. ENTIRE_AUTH_BASE_URL takes precedence; otherwise it falls back to
// DefaultAuthBaseURL (split-host by default).
//
// The result is canonicalised — lowercased scheme/host, default port stripped,
// path/query/fragment dropped, trailing slash collapsed — so the value that
// flows into store.SaveToken keys matches what tokenmanager.New emits after
// its own NormalizeOriginURL pass. Without this, a user setting
// ENTIRE_AUTH_BASE_URL=https://AUTH.example.com:443/ would log in successfully
// (saved under the raw form) but every subsequent data-API command would
// resolve "not logged in" because the manager probes under the normalised
// "https://auth.example.com".
func AuthBaseURL() string {
	raw := strings.TrimSpace(os.Getenv(AuthBaseURLEnvVar))
	if raw == "" {
		raw = DefaultAuthBaseURL
	}
	return NormalizeOriginURL(raw)
}

// IsSplitHost reports whether the CLI is configured for split-host —
// i.e. ENTIRE_AUTH_BASE_URL points at a different origin than the data
// API. Both sides are canonicalised via NormalizeOriginURL before
// comparison: AuthBaseURL already does this internally, but BaseURL
// only trims whitespace and a trailing slash, so a cosmetically-
// different ENTIRE_API_BASE_URL (uppercase host, explicit :443, path
// suffix) would otherwise look split when it isn't.
func IsSplitHost() bool {
	return AuthBaseURL() != NormalizeOriginURL(BaseURL())
}

// ResolveURL joins an API-relative path against the effective base URL.
func ResolveURL(path string) (string, error) {
	return ResolveURLFromBase(BaseURL(), path)
}

// ResolveURLFromBase joins an API-relative path against an explicit base URL.
// Only http and https schemes are accepted.
func ResolveURLFromBase(baseURL, path string) (string, error) {
	base, err := url.Parse(baseURL)
	if err != nil {
		return "", fmt.Errorf("parse base URL: %w", err)
	}

	if base.Scheme != schemeHTTP && base.Scheme != schemeHTTPS {
		return "", fmt.Errorf("unsupported base URL scheme %q (must be http or https)", base.Scheme)
	}

	rel, err := url.Parse(path)
	if err != nil {
		return "", fmt.Errorf("parse path: %w", err)
	}

	return base.ResolveReference(rel).String(), nil
}

// RequireSecureURL returns ErrInsecureHTTP if the base URL uses the http scheme.
// Call this before making authenticated requests unless --insecure-http-auth is set.
func RequireSecureURL(baseURL string) error {
	u, err := url.Parse(baseURL)
	if err != nil {
		return fmt.Errorf("parse base URL: %w", err)
	}

	if u.Scheme == schemeHTTP {
		return ErrInsecureHTTP
	}

	return nil
}

func normalizeBaseURL(raw string) string {
	return strings.TrimRight(strings.TrimSpace(raw), "/")
}

// NormalizeOriginURL canonicalises an origin URL the same way auth-go's
// tokenmanager does internally: lowercase scheme/host, default port stripped
// (80 for http, 443 for https), path/query/fragment dropped, trailing slash
// collapsed. On parse failure, raw is returned unchanged so non-URL audience
// values still compare byte-for-byte.
//
// Mirrors auth-go's internal/oauthhttp.NormalizeOriginURL so the value the
// CLI hands to the manager as Issuer survives the manager's own normalisation
// pass byte-for-byte — see AuthBaseURL.
func NormalizeOriginURL(raw string) string {
	trimmed := strings.TrimSpace(raw)
	u, err := url.Parse(trimmed)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return trimmed
	}
	scheme := strings.ToLower(u.Scheme)
	hostname := strings.ToLower(u.Hostname())
	port := u.Port()
	dropPort := port == "" ||
		(scheme == schemeHTTP && port == "80") ||
		(scheme == schemeHTTPS && port == "443")

	out := url.URL{Scheme: scheme}
	switch {
	case dropPort && strings.Contains(hostname, ":"):
		out.Host = "[" + hostname + "]"
	case dropPort:
		out.Host = hostname
	case strings.Contains(hostname, ":"):
		out.Host = "[" + hostname + "]:" + port
	default:
		out.Host = hostname + ":" + port
	}
	return out.String()
}

// OriginOnly is a backwards-compatible alias for NormalizeOriginURL.
// Callers reading raw URLs (e.g. ENTIRE_SEARCH_URL) and feeding them into
// tokenmanager.TokenRequest.Resource use this to strip path/query/fragment
// before the lib's stricter origin-only validator runs.
func OriginOnly(raw string) string {
	return NormalizeOriginURL(raw)
}

