				"verification_uri_complete": serverURLWithPath(r, "/approve?code=WXYZ-0000"),
				"expires_in":                10,
				"interval":                  1,
			})
		case r.Method == http.MethodPost && r.URL.Path == "/oauth/token":
			writeJSON(t, w, http.StatusBadRequest, map[string]any{"error": "expired_token"})
		default:
			http.NotFound(w, r)
		}
	}))
